import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import '../services/api_client.dart';
import 'home_screen.dart';
class LoginScreen extends StatefulWidget{const LoginScreen({super.key});@override State<LoginScreen> createState()=>_LoginScreenState();}
class _LoginScreenState extends State<LoginScreen>{final site=TextEditingController(),user=TextEditingController(),password=TextEditingController();bool busy=false;String error='';@override void initState(){super.initState();SharedPreferences.getInstance().then((p){if(mounted){site.text=p.getString('employee_hub_site')??'';user.text=p.getString('employee_hub_user')??'';}});}@override void dispose(){site.dispose();user.dispose();password.dispose();super.dispose();}Future<void> submit()async{setState(() { busy=true; error=''; });try{final api=await ApiClient.login(site.text,user.text,password.text);if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomeScreen(api:api,username:user.text)));}catch(e){if(mounted)setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(() { busy=false; });}}@override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('AH  EMPLOYEE HUB',style:TextStyle(fontWeight:FontWeight.w900,fontSize:20)),const SizedBox(height:12),const Text('Your workday, in one place.'),field('ERPNext site URL',site),field('Username or email',user),field('Password',password,obscure:true),if(error.isNotEmpty)Text(error,style:const TextStyle(color:Colors.red)),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:submit,child:Text(busy?'Signing in…':'Sign in securely'))),const Text('Use HTTPS outside local development.',style:TextStyle(fontSize:11))])))))));Widget field(String label,TextEditingController c,{bool obscure=false})=>Padding(padding:const EdgeInsets.only(top:14),child:TextField(controller:c,obscureText:obscure,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));}
